vehicleSpecs['chery:arrizo8']={"title":"CHERY ARRIZO 8 — данные официального руководства","source":"руководство CHERY ARRIZO 8, стр. 254–261 и 267; https://1.cdn.perxis.ru/originals/cp7gtaqto5rf56sq3tqg/original; актуальная модель: https://www.chery.ru/models/arrizo8/","items":["Актуальная российская версия: двигатель SQRF4J16C, 150 л.с., 7DCT, передний привод. Таблица жидкостей руководства приводит моторное масло только для SQRF4J16 без суффикса C; допуск и объём для SQRF4J16C подтвердить по VIN и сервисной документации","Коробка 730DHB (7DCT): Sinopec DCTF-GS — справочная ёмкость 4,25 ± 0,2 л; руководство предписывает объём заливки по объёму слива при отсутствии утечек, фактический уровень — по сервисной процедуре","Охлаждающая жидкость LEC-II в таблице указана для SQRF4J16 без суффикса C; объём для текущего SQRF4J16C подтвердить по VIN. Тормозная жидкость DOT4","Свечи зажигания 3707AAG — замена каждые 30 000 км","На каждом ТО: масло двигателя с фильтром, воздушный и салонный фильтры","Внешний топливный фильтр — каждые 30 000 км; жидкость 7DCT — каждые 60 000 км","Тормозная жидкость — каждые 2 года или 40 000 км; обычное ТО — каждые 12 месяцев или 10 000 км","При тяжёлых условиях: обслуживание каждые 6 месяцев или 5 000 км","Первое обслуживание нового автомобиля: через 2 месяца или 5 000 км, отдельно от плановых ТО-1 — ТО-8","Дроссельная заслонка: очистка рекомендуется каждые 15 000 км, включая промежуточные пробеги между ТО; углы установки колёс — проверка каждые 20 000 км","Шланг заливной горловины: стандартный каучук NBR+PVC/CSM — замена через 5 лет или 200 000 км; фторкаучук — через 10 лет или 500 000 км. Материал подтвердить по автомобилю","Руководство содержит условные строки для разных комплектаций: цепь ГРМ без плановой замены; интервал ремня применяется только при подтверждённом ременном приводе. Для российской 2WD операции раздатки и заднего дифференциала не назначаются","Воздушный и салонный фильтры в пыльных условиях менять чаще; артикулы фильтров, шлангов и применимость свечей 3707AAG подтвердить по VIN"]};
vehicleSpecs['chery:tiggo7pm']={title:'CHERY TIGGO 7 PRO MAX — данные официального руководства',source:'руководство CHERY Tiggo 7 Pro Max (рестайлинг 2024), раздел 7, стр. 253–258; https://1.cdn.perxis.ru/originals/crfa1fqto5r6o3lgm5cg/original',items:['SQRF4J16C: моторное масло Castrol SN/SP 5W-30 — 4,3 ± 0,2 л с одновременной заменой масляного фильтра','DCT 730DHB/DHC: Sinopec DCTF-GS — 4,25 ± 0,2 л; замена каждые 60 000 км','Для AWD: раздаточная коробка SAE 80W-90 — 0,31 ± 0,03 л; задний дифференциал SAE 80W-90 — 0,44 ± 0,03 л','Для AWD: устройство передачи момента Castrol HALBOT 311 — 0,63 ± 0,03 л; замена каждые 60 000 км','Масла раздатки и заднего дифференциала: обычные условия — каждые 160 000 км; тяжёлые — каждый год или 38 000 км','Охлаждающая жидкость LEC-II — 7,5 л; тормозная жидкость DOT4; свечи 3707AAG','На каждом ТО: моторное масло с фильтром, воздушный и салонный фильтры','Свечи и внешний топливный фильтр — каждые 30 000 км; тормозная жидкость — каждые 2 года или 40 000 км','Обычный интервал ТО — 12 месяцев или 10 000 км; объёмы жидкостей справочные, фактическая заправка зависит от процедуры']};
vehicleSpecs['chery:tiggo7phev']={title:'CHERY TIGGO 7 PRO Plug-in Hybrid — данные официального руководства',source:'руководство CHERY Tiggo 7 PRO Plug-in Hybrid, раздел 7, стр. 248–258; https://1.cdn.perxis.ru/originals/clu48sieibkv5v0oeh2g/original',items:['SQRE4T15C: моторное масло Castrol SN/SP 5W-30, Lukoil SN 5W-40, Total SN+/SP 5W-30, Shell SN+ 5W-30/SN 5W-40 или Fuchs SN 5W-40 — 4,7 ± 0,2 л с заменой фильтра','Гибридная трансмиссия 351HHA: Fuchs TITAN EG DHT5105 — 7,2 ± 0,2 л; жидкость и внешний фильтр менять через 4 года или 40 000 км','Высокотемпературный контур охлаждения LEC-II — 10,5 ± 0,5 л; низкотемпературный — 2,7 ± 0,2 л','Охлаждающая жидкость обоих контуров и тормозная жидкость DOT4 — замена каждые 2 года или 40 000 км','На каждом ТО: моторное масло с фильтром; свечи, воздушный и салонный фильтры — проверка и замена при необходимости','Внешний топливный фильтр — замена каждые 30 000 км; внутренний фильтр встроен в топливный насос и планово не обслуживается','Осмотр тяговой батареи и высоковольтных разъёмов выполнять по процедуре без вскрытия и отключения при обычном ТО','Обычный интервал ТО — 12 месяцев или 10 000 км; тяжёлые условия — 6 месяцев или 5 000 км']};
vehicleSpecs['chery:tiggo8phev']={title:'CHERY TIGGO 8 PRO Plug-in Hybrid — данные официального руководства',source:'руководство CHERY Tiggo 8 PRO Plug-in Hybrid, раздел 7, стр. 247–254; https://1.cdn.perxis.ru/originals/clu49maeibkv5v0oeh4g/original',items:['SQRE4T15C: моторное масло Castrol SN/SP 5W-30, Lukoil SN 5W-40, Total SN+/SP 5W-30, Shell SN+ 5W-30/SN 5W-40 или Fuchs SN 5W-40 — 4,7 ± 0,2 л с заменой фильтра','Гибридная трансмиссия 351HHA: Fuchs TITAN EG DHT5105 — 7,2 ± 0,2 л; жидкость и внешний фильтр менять через 4 года или 40 000 км','Высокотемпературный контур охлаждения LEC-II — 12,7 ± 0,57 л; низкотемпературный — 2,7 ± 0,2 л','Охлаждающая жидкость обоих контуров и тормозная жидкость DOT4 — замена каждые 2 года или 40 000 км','На каждом ТО: моторное масло с фильтром, воздушный и салонный фильтры','Свечи зажигания и внешний топливный фильтр — замена каждые 30 000 км','Для отдельных вариантов: угольный фильтр адсорбера — каждые 3 года или 60 000 км; ремень ГРМ — каждые 3 года или 100 000 км','Очистка дроссельной заслонки рекомендуется каждые 15 000 км; углы установки колёс проверять каждые 20 000 км','Осмотр тяговой батареи и высоковольтных разъёмов выполнять по процедуре без вскрытия и отключения при обычном ТО','Обычный интервал ТО — 12 месяцев или 10 000 км; тяжёлые условия — 6 месяцев или 5 000 км']};
vehicleSpecs['chery:tiggo9']={title:'CHERY TIGGO 9 — данные из официального руководства',source:'руководство CHERY Tiggo 9, стр. 302–309; https://1.cdn.perxis.ru/originals/cth99pato5r5uhvcp5dg/original',items:['Двигатель SQRF4J20 2.0 TGDI: моторное масло C5 0W-20 — 4,5 ± 0,2 л с одновременной заменой масляного фильтра','8AT AWD: ATF-GS — справочная ёмкость 6,6 ± 0,2 л; замена с наружным фильтром через 5 лет или 60 000 км, что наступит раньше','Раздаточная коробка: FUCHS TITAN EG 3202 — 0,4 ± 0,02 л; задний дифференциал: Castrol SAF CARBON MOD — 0,6 ± 0,02 л; замена обоих масел каждые 50 000 км','Охлаждающая жидкость OAT — 7,5 л; в напечатанном допуске объёма руководства указана несогласованная размерность, поэтому допуск здесь не приводится','Тормозная жидкость DOT4 — 0,8 л; замена каждые 2 года или 40 000 км','На каждом ТО: моторное масло с фильтром, воздушный фильтр двигателя и фильтр кондиционера','Свечи зажигания и внешний топливный фильтр: замена каждые 30 000 км','Обычный межсервисный интервал: 10 000 км или 12 месяцев; при тяжёлых условиях моторное масло меняется чаще','Топливо АИ-92; бак 65 л; заправочные ёмкости справочные, фактический объём — по процедуре']};
vehicleSpecs['chery:tiggo9'].items.push('Первое обслуживание: 2 месяца или 5 000 км; восемь выбранных ТО — обычная сетка 10 000 км / 12 месяцев', 'В тяжёлых условиях масло и обслуживание каждые 5 000 км или 6 месяцев; при запылённости фильтры менять чаще', 'На каждом ТО: приборы/мультимедиа/диагностика, очистители/омыватели и климат, температура антифриза/влага DOT4, рулевая колонка/чехлы, давление запаски, перестановка колёс и герметичность поддона/пробки', 'Рекомендуется очищать дроссель каждые 15 000 км; углы четырёх колёс проверять через 20 000 км', 'Если установлен угольный фильтр адсорбера: замена 3 года / 60 000 км. Шланг адсорбера: 10 лет / 500 000 км; шланг горловины NBR+PVC/CSM: 5 лет / 200 000 км, фторкаучук: 10 лет / 500 000 км', 'Артикулы фильтров, свечей, уплотнений и материал шлангов подтвердить по VIN; сроки ГРМ в этой таблице не назначены', 'Для 8AT при отсутствии утечек учитывать объём слитой жидкости; справочную ёмкость не использовать как безусловный объём заливки');
const bestuneCardData={t55:{title:'BESTUNE T55 — официальные технические данные',source:'официальные материалы BESTUNE T55',items:['Двигатель 1.5 л Turbo, 160 л.с., 258 Н·м','7-ступенчатая роботизированная коробка DCT','Передний привод; топливо АИ-92/АИ-95']},t77:{title:'BESTUNE T77 — официальные технические данные',source:'официальная страница BESTUNE T77',items:['Двигатель 1.5 л Turbo, 160 л.с., 258 Н·м','7-ступенчатая роботизированная коробка DCT с мокрым сцеплением; встречалась версия 6MT','Передний привод']},b70:{title:'BESTUNE B70 — официальные технические данные',source:'официальная страница BESTUNE B70',items:['Двигатели 1.5 л и 2.0 л Turbo','Коробки 6AT Aisin или DCT по комплектации','Передний привод']},t90:{title:'BESTUNE T90 — официальные технические данные',source:'официальная страница BESTUNE T90',items:['Двигатель 1.5 л Turbo 160 л.с. или 2.0 л Turbo 245 л.с.','7 DCT для 1.5T или Aisin 8AT для 2.0T','Передний привод; топливо АИ-92/АИ-95']}};
