function gearboxesFor(brand,model,variant){return gearboxOptions[brand+':'+model+':'+variant]||gearboxOptions[brand+':'+model]}
function fillGearboxes(reset=false){
 const brand=$('car-brand').value,model=$('jetour-model').value,variant=$('powertrain').value,context=brand+':'+model+':'+variant;
 const gearboxes=gearboxesFor(brand,model,variant),gearbox=$('gearbox-code'),selected=reset||gearbox.dataset.context!==context?'unknown':gearbox.value;
 gearbox.dataset.context=context;
 $('gearbox-wrap').hidden=!gearboxes;
 gearbox.innerHTML=gearboxes?Object.entries(gearboxes).map(([value,label])=>`<option value="${value}">${label}</option>`).join(''):'';
 if(gearboxes?.[selected])gearbox.value=selected;
}
